-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/notebook/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, ROW_H, GAP = 20, 56, 10
local BOX_W = kit.W - 40      -- refreshed in layout(): an app may set kit.W, kit.H for a landscape screen
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  BOX_W = kit.W - 40
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

local __mods, __loaded = {}, {}
local function require(n)
  local v = __loaded[n]
  if v ~= nil then return v end
  local f = __mods[n]
  if not f then error('module not found: ' .. tostring(n)) end
  v = f()
  if v == nil then v = true end
  __loaded[n] = v
  return v
end

__mods['book'] = function()
-- Notebook's notes: one plain text file per note in the app's folder on the card
-- (AppFiles/notebook/, ctx.files), so they can be read and written on a computer too:
--
--   Shopping list                 the title
--   folder: Home                  optional
--   tags: weekly, market          optional
--   edited: 2026-11-06 14:30      written by the app
--   created: 2026-11-06 14:02     written by the app
--                                 a blank line, then the blocks, one blank line between them
--   First block...
--
-- A file without these lines works too: its first line is the title, the rest the text. The
-- folder cannot have subfolders (ctx.files), so a note's folder is the "folder:" line.
--
-- The list needs each note's title, folder, tags and dates without reading every file at each
-- start: an index (index.txt in ctx.storage) keeps them by file name and size, and only files
-- that are new or changed in size are read again.

local B = {}

B.MAX_BLOCK = 512                 -- characters per block (the docked keyboard's limit)
B.MAX_FILE = 200000               -- bytes a note may grow to (a write takes at most 262144)
local HEAD_BYTES = 4096

------------------------------------------------------------------ files

local function files() return ctx.files end

function B.list_files()
  local ok, list = pcall(function() return files():list() end)
  if not ok or type(list) ~= 'table' then return {} end
  local out = {}
  for _k, f in ipairs(list) do
    if type(f.name) == 'string' and f.name:lower():match('%.txt$') then out[#out + 1] = { name = f.name, size = f.size or 0 } end
  end
  return out
end

function B.read(name, len)
  local parts, pos = {}, 0
  while true do
    local ok, chunk = pcall(function() return files():read(name, pos, 65536) end)
    if not ok or type(chunk) ~= 'string' then return #parts > 0 and table.concat(parts) or nil end
    parts[#parts + 1] = chunk
    pos = pos + #chunk
    if #chunk < 65536 or (len and pos >= len) or pos >= B.MAX_FILE then break end
  end
  return table.concat(parts)
end

function B.write(name, s)
  local ok, r, err = pcall(function() return files():write(name, s) end)
  if not ok then return nil, tostring(r) end
  if not r then return nil, tostring(err) end
  return true
end

function B.remove(name) pcall(function() files():remove(name) end) end

function B.exists(name)
  local ok, r = pcall(function() return files():exists(name) end)
  return ok and r == true
end

------------------------------------------------------------------ text

-- lower case for search, Turkish and other accented capitals too; I, İ and ı all become i, so
-- "istanbul" finds "İstanbul" and "ISTANBUL" alike
local FOLD = {
  ['İ'] = 'i', ['I'] = 'i', ['ı'] = 'i', ['Ç'] = 'ç', ['Ğ'] = 'ğ', ['Ö'] = 'ö', ['Ş'] = 'ş', ['Ü'] = 'ü',
  ['Ä'] = 'ä', ['Â'] = 'â', ['Á'] = 'á', ['À'] = 'à', ['É'] = 'é', ['È'] = 'è', ['Ê'] = 'ê', ['Í'] = 'í',
  ['Î'] = 'î', ['Ó'] = 'ó', ['Ô'] = 'ô', ['Ú'] = 'ú', ['Û'] = 'û', ['Ñ'] = 'ñ', ['Å'] = 'å', ['Ø'] = 'ø',
}
-- (only A-Z by hand: string.lower follows the C locale and may change bytes of UTF-8 letters)
function B.fold(s)
  s = s:gsub('[%z\1-\127\194-\244][\128-\191]*', function(c) return FOLD[c] end)
  return (s:gsub('[A-Z]', function(c) return string.char(c:byte() + 32) end))
end

local function trim(s) return (s:gsub('^%s+', ''):gsub('%s+$', '')) end
B.trim = trim

-- a block longer than the keyboard takes is cut at a line break or a space before the limit
local function cut(p, out)
  while utf8.len(p) and utf8.len(p) > B.MAX_BLOCK do
    local stop = utf8.offset(p, B.MAX_BLOCK + 1) - 1
    local head = p:sub(1, stop)
    local at = head:match('^.*()\n') or head:match('^.*() ')
    if not at or at < stop // 2 then at = stop + 1 end
    out[#out + 1] = trim(p:sub(1, at - 1))
    p = trim(p:sub(at))
  end
  if p ~= '' then out[#out + 1] = p end
end

-- the blocks of a text: blank lines part them
function B.blocks(text)
  local out = {}
  text = (text or ''):gsub('\r', '')
  for raw in (text .. '\n\n'):gmatch('(.-)\n%s*\n') do
    local p = trim(raw)
    if p ~= '' then cut(p, out) end
  end
  return out
end

-- a note from a file's text
function B.parse(s)
  s = (s or ''):gsub('\r', ''):gsub('^\239\187\191', '')
  local n = { title = '', folder = '', tags = {}, edited = '', created = '', paras = {} }
  local first, rest = s:match('^([^\n]*)\n?(.*)$')
  n.title = trim(first or '')
  rest = rest or ''
  while true do
    local line, after = rest:match('^([^\n]*)\n?(.*)$')
    if not line then break end
    local k, v = line:match('^(%a+):%s*(.-)%s*$')
    if k == 'folder' then n.folder = v
    elseif k == 'tags' then n.tags = B.split_tags(v)
    elseif k == 'edited' then n.edited = v
    elseif k == 'created' then n.created = v
    else break end
    rest = after
  end
  n.paras = B.blocks(rest)
  if n.title == '' then n.title = 'Untitled' end
  return n
end

function B.split_tags(s)
  local out, seen = {}, {}
  for raw in (s or ''):gmatch('[^,]+') do
    local t = trim(raw)
    if t ~= '' and not seen[B.fold(t)] then seen[B.fold(t)] = true; out[#out + 1] = t end
  end
  return out
end

function B.format(n)
  local t = { n.title }
  if n.folder ~= '' then t[#t + 1] = 'folder: ' .. n.folder end
  if #n.tags > 0 then t[#t + 1] = 'tags: ' .. table.concat(n.tags, ', ') end
  if n.edited ~= '' then t[#t + 1] = 'edited: ' .. n.edited end
  if n.created ~= '' then t[#t + 1] = 'created: ' .. n.created end
  return table.concat(t, '\n') .. '\n\n' .. table.concat(n.paras, '\n\n') .. '\n'
end

------------------------------------------------------------------ file names

local RESERVED = { con = 1, prn = 1, aux = 1, nul = 1 }
for i = 1, 9 do RESERVED['com' .. i] = 1; RESERVED['lpt' .. i] = 1 end

-- a file name for a title: what the card allows, at most 60 bytes, not taken by another note
function B.file_name(title, taken)
  local s = title:gsub('[%c/\\:%*%?"<>|~]', ' '):gsub('%s+', ' ')
  s = trim(s):gsub('^%.+', '')
  while #s > 60 do s = s:gsub('[%z\1-\127\194-\244][\128-\191]*$', '') end
  s = s:gsub('[%. ]+$', '')
  if s == '' then s = 'Note' end
  if RESERVED[s:lower()] then s = s .. '_' end
  local name, k = s .. '.txt', 2
  while taken(name) do name = s .. ' ' .. k .. '.txt'; k = k + 1 end
  return name
end

------------------------------------------------------------------ the index

local SEP = '\t'
local function clean(s) return (tostring(s or ''):gsub('[\t\n\r]', ' ')) end

-- a list entry from a note: what the list shows and filters on
function B.entry(name, size, n)
  local snip = (n.paras[1] or ''):gsub('%s+', ' ')
  if #snip > 120 then snip = snip:sub(1, 120):gsub('[%z\1-\127\194-\244][\128-\191]*$', '') end
  return { name = name, size = size, title = n.title, folder = n.folder, tags = n.tags,
           edited = n.edited, created = n.created, snip = snip }
end

function B.load_index()
  local ok, s = pcall(function() return ctx.storage:read('index.txt') end)
  local out = {}
  if not ok or type(s) ~= 'string' then return out end
  for line in s:gmatch('[^\n]+') do
    local f = {}
    for v in (line .. SEP):gmatch('([^\t]*)\t') do f[#f + 1] = v end
    if #f >= 8 then
      out[f[1]] = { name = f[1], size = tonumber(f[2]) or -1, title = f[3], folder = f[4], tags = B.split_tags(f[5]),
                    edited = f[6], created = f[7], snip = f[8] }
    end
  end
  return out
end

function B.save_index(entries)
  local t = {}
  for _k, e in ipairs(entries) do
    t[#t + 1] = table.concat({ clean(e.name), e.size, clean(e.title), clean(e.folder), clean(table.concat(e.tags, ', ')),
                               clean(e.edited), clean(e.created), clean(e.snip) }, SEP)
  end
  pcall(function() ctx.storage:write('index.txt', table.concat(t, '\n')) end)
end

-- the list's entries: the index where a file's size is the same, else read again (step(k, n)
-- is called after each file read, for progress and to give the host time)
function B.scan(step)
  local idx = B.load_index()
  local out, changed = {}, false
  local fl = B.list_files()
  for k, f in ipairs(fl) do
    local e = idx[f.name]
    if not e or e.size ~= f.size then
      local n = B.parse(B.read(f.name, HEAD_BYTES) or '')
      e = B.entry(f.name, f.size, n)
      changed = true
      if step then step(k, #fl) end
    end
    out[#out + 1] = e
  end
  if changed or #out ~= (function() local c = 0; for _ in pairs(idx) do c = c + 1 end; return c end)() then B.save_index(out) end
  return out
end

-- the line of a note that holds the folded query, shortened around it (nil: not found)
function B.find(text, q)
  for raw in (text .. '\n'):gmatch('([^\n]*)\n') do
    local line = raw
    local f = B.fold(line)
    local at = f:find(q, 1, true)
    if at then
      line = trim(line)
      if #line > 90 then
        local start = math.max(1, at - 30)
        while start > 1 and line:byte(start) >= 128 and line:byte(start) < 192 do start = start - 1 end
        line = (start > 1 and '…' or '') .. line:sub(start, start + 89):gsub('[%z\1-\127\194-\244][\128-\191]*$', '')
      end
      return line
    end
  end
  return nil
end

return B
end

-- Notebook for XTOS Licorice (uses tools/gamekit): plain text notes kept as .txt files in
-- AppFiles/notebook/ on the card (book.lua has the format), written block by block.
--
-- The list: every note with its folder, tags, date and first words; Folder and Tag filter it,
-- Sort orders it (last edited, title, created), Search looks through all notes and shows the
-- line it found. A note: its blocks, a page at a time; tap one to edit it in place with the
-- docked keyboard (2.9), where Enter makes a new line and Save / Cancel sit above the keyboard
-- (a blank line splits it in two, an empty one is deleted); Add puts one at the end.
-- Menu: rename, folder, tags, delete.

local B = require('book')

local W, H = kit.W, kit.H
local TOP_H = 50
local ROW_H = 78
local BTN_Y, BTN_H = 704, 60
local BODY_Y, BODY_END = 84, 690
local PARA_GAP = 16

local screen = 'list'           -- list, note, edit, pick
local entries = {}              -- every note: { name, size, title, folder, tags, edited, created, snip }
local filt = { folder = nil, tag = nil }   -- folder: nil all, '' none, else its name; tag: nil all
local sort = 'edited'
local page = 1
local search = nil              -- { q, hits = { [name] = line }, done, at, n }
local cur = nil                 -- the open note: { name, n, page }
local edit = nil                -- { i (block, nil: new), after, text, start, prev, ed }
local pick = nil                -- { title, items = { {label, fn} }, page }
local msg, ERR = nil, nil

------------------------------------------------------------------ helpers

local function now_text()
  local ok, t = pcall(function() return ctx.clock:now() end)
  if not ok or type(t) ~= 'table' or not t.valid or not t.year then return '' end
  return string.format('%04d-%02d-%02d %02d:%02d', t.year, t.month, t.day, t.hour, t.minute)
end

local function extend() pcall(function() ctx.budget:extend() end) end

local function kb_h()
  local ok, h = pcall(function() return ctx.input.keyboard_h end)
  return (ok and tonumber(h)) or 436
end

local function save_settings()
  kit.write('settings.txt', 'sort=' .. sort .. '\nfolder=' .. (filt.folder == nil and '*' or filt.folder) ..
    '\ntag=' .. (filt.tag or '*'))
end

local function load_settings()
  local t = kit.kv(kit.read('settings.txt'))
  sort = (t.sort == 'title' or t.sort == 'created') and t.sort or 'edited'
  filt.folder, filt.tag = nil, nil
  if t.folder and t.folder ~= '*' then filt.folder = t.folder end
  if t.tag and t.tag ~= '*' and t.tag ~= '' then filt.tag = t.tag end
end

local function has_tag(e, tag)
  local f = B.fold(tag)
  for _k, t in ipairs(e.tags) do if B.fold(t) == f then return true end end
  return false
end

local function entry_of(name)
  for k, e in ipairs(entries) do if e.name == name then return e, k end end
end

local function taken_by_other(own)
  return function(name)
    local lname = name:lower()
    if own and own:lower() == lname then return false end
    for _k, e in ipairs(entries) do if e.name:lower() == lname then return true end end
    return B.exists(name)
  end
end

-- the notes the list shows: a search covers every note, else the folder and tag filters apply
local function visible()
  local out = {}
  for _k, e in ipairs(entries) do
    local ok
    if search then ok = search.hits[e.name] ~= nil
    else
      ok = (filt.folder == nil or e.folder == filt.folder) and (filt.tag == nil or has_tag(e, filt.tag))
    end
    if ok then out[#out + 1] = e end
  end
  table.sort(out, function(a, b)
    if sort == 'title' then
      local fa, fb = B.fold(a.title), B.fold(b.title)
      if fa ~= fb then return fa < fb end
    elseif sort == 'created' then
      if a.created ~= b.created then return a.created > b.created end
    elseif a.edited ~= b.edited then return a.edited > b.edited end
    return a.name < b.name
  end)
  return out
end

local function list_top() return search and 136 or 108 end
local function per_page() return (BODY_END - list_top()) // ROW_H end
local function pages(n) return math.max(1, (n + per_page() - 1) // per_page()) end

local function folders()
  local seen, out, none = {}, {}, 0
  for _k, e in ipairs(entries) do
    if e.folder == '' then none = none + 1
    elseif not seen[e.folder] then seen[e.folder] = 0; out[#out + 1] = e.folder end
    if e.folder ~= '' then seen[e.folder] = seen[e.folder] + 1 end
  end
  table.sort(out, function(a, b) return B.fold(a) < B.fold(b) end)
  return out, seen, none
end

local function tags()
  local seen, out = {}, {}
  for _k, e in ipairs(entries) do
    for _j, t in ipairs(e.tags) do
      local f = B.fold(t)
      if not seen[f] then seen[f] = { t, 0 }; out[#out + 1] = f end
      seen[f][2] = seen[f][2] + 1
    end
  end
  table.sort(out)
  local list = {}
  for _k, f in ipairs(out) do list[#list + 1] = { seen[f][1], seen[f][2] } end
  return list
end

------------------------------------------------------------------ notes on the card

local function store_note(name, n)
  local s = B.format(n)
  if #s > B.MAX_FILE then return nil, 'The note is too long (200 KB at most).' end
  local ok, err = B.write(name, s)
  if not ok then return nil, 'Not saved: ' .. kit.short(tostring(err), 30) end
  local e = B.entry(name, #s, n)
  local old, k = entry_of(name)
  if old then entries[k] = e else entries[#entries + 1] = e end
  B.save_index(entries)
  return true
end

local function open_note(name)
  local s = B.read(name)
  if not s then msg = 'Could not read ' .. kit.short(name, 30) .. '.'; return end
  cur = { name = name, n = B.parse(s), page = 1 }
  screen = 'note'
  msg = nil
end

------------------------------------------------------------------ laying out a note

-- the note's pages: each a list of { i (block), lines, y }; a block taller than a page
-- goes on over several
local function note_pages()
  local f = 'medium'
  local lh = kit.line_h(f) + 2
  local out, pg, y = {}, {}, BODY_Y
  for pi, p in ipairs(cur.n.paras) do
    local lines = kit.wrap(p, f, W - 32)
    local k = 1
    while k <= #lines do
      local room = (BODY_END - y) // lh
      if room < 1 or (k == 1 and room < math.min(#lines, 3) and #pg > 0) then
        out[#out + 1] = pg; pg, y = {}, BODY_Y
        room = (BODY_END - y) // lh
      end
      local take = {}
      for j = k, math.min(#lines, k + room - 1) do take[#take + 1] = lines[j] end
      pg[#pg + 1] = { i = pi, lines = take, y = y }
      y = y + #take * lh + PARA_GAP
      k = k + #take
    end
  end
  out[#out + 1] = pg
  return out
end

------------------------------------------------------------------ editing a block

-- A note is a list of blocks (n.paras) of at most 512 characters: the docked keyboard takes no
-- more in one edit. Writing on at the end of a block that reaches CONTINUE_AT goes on in a new
-- block below it, the keyboard kept open, cut at the last space or line break so that no word is
-- split. (Typing in the middle of a full block just stops at 512.)
local CONTINUE_AT = 500

-- put the edited text into the note (a blank line makes two blocks, empty removes the block) and
-- write the note; returns the index of the last block written (or the one before) and whether
-- anything changed
local function put_block(e, text)
  local n = cur.n
  local new = B.blocks(text or '')
  local at
  if e.i then
    if #new == 1 and new[1] == n.paras[e.i] then return e.i, false end
    table.remove(n.paras, e.i)
    at = e.i
  else
    if #new == 0 then return e.after or #n.paras, false end
    at = (e.after or #n.paras) + 1
  end
  for j = #new, 1, -1 do table.insert(n.paras, at, new[j]) end
  n.edited = now_text()
  local ok, err = store_note(cur.name, n)
  msg = ok and ((e.i and #new == 0) and 'Block deleted.' or 'Saved.') or err
  return at + #new - 1, true
end

local function finish_edit(text, keep)
  local e = edit
  edit = nil
  screen = 'note'
  if not keep or not cur then return end
  local target, changed = put_block(e, text)
  if not changed then return end
  -- show the page with the block just written
  for k, pg in ipairs(note_pages()) do
    for _j, b in ipairs(pg) do if b.i == target then cur.page = k; return end end
  end
end

local function edit_rect()
  local bottom = H - kb_h() - 30
  return { x = 16, y = TOP_H + 14, w = W - 32, h = math.max(40, bottom - TOP_H - 14) }
end

local start_edit

-- the block being written at its end is nearly full: keep it (up to its last space or line
-- break) and go on in a new block below with the rest, the keyboard staying up
local function continue_block()
  local e = edit
  local t = e.text
  local cut = t:match('^.*()[ \n]')
  local head, carry = t, ''
  if cut and cut > #t // 2 then head, carry = t:sub(1, cut - 1), t:sub(cut + 1) end
  pcall(function() e.ed:close() end)
  e.ed, edit = nil, nil
  local last = put_block(e, head)
  start_edit(nil, last, carry)
end

-- edit block i, or (i nil) a new block after block `after` (nil: at the end), starting with carry
start_edit = function(i, after, carry)
  local text = i and cur.n.paras[i] or (carry or '')
  edit = { i = i, after = after, text = text, start = i and text or '', prev = text }
  screen = 'edit'
  msg = nil
  local ok, ed = pcall(function()
    return ctx.input:edit({
      rect = edit_rect(), text = text, max_chars = B.MAX_BLOCK, multiline = true, enter = 'newline',
      placeholder = i and '' or 'Write here. Enter starts a new line.',
      on_change = function(c, t)
        local e = edit
        if not e then return end
        local appended = #t > #e.prev and t:sub(1, #e.prev) == e.prev
        e.text, e.prev = t, t
        if appended and (utf8.len(t) or 0) >= CONTINUE_AT then continue_block() end
        kit.refresh()
      end,
      on_end = function(c, t, how)
        -- Back ends the editing: keep the text if it changed, after asking
        if not edit then return end
        edit.ed = nil
        edit.text = t or edit.text
        if edit.text == edit.start then finish_edit(nil, false)
        else
          kit.show({ title = 'Save the changes?', rows = { { { 'Save', function() kit.close(); finish_edit(edit.text, true) end },
                                                            { 'Discard', function() kit.close(); finish_edit(nil, false) end } } } })
        end
        kit.refresh()
      end,
    })
  end)
  if ok and ed then
    edit.ed = ed
    -- carried-over text: the cursor goes to its end
    if not i and text ~= '' then pcall(function() ed:set_text(text) end) end
  else
    edit, screen = nil, 'note'
    msg = 'The keyboard could not open.'
  end
end

local function save_edit()
  if not edit then return end
  local t = edit.text
  if edit.ed then
    local ok, s = pcall(function() return edit.ed:close() end)
    if ok and type(s) == 'string' then t = s end
  end
  finish_edit(t, true)
end

local function cancel_edit()
  if not edit then return end
  if edit.ed then pcall(function() edit.ed:close() end) end
  finish_edit(nil, false)
end

------------------------------------------------------------------ search

local step_search

local function start_search(q)
  q = B.trim(q or '')
  if q == '' then search = nil; return end
  search = { q = q, f = B.fold(q), hits = {}, at = 0, n = #entries, done = false }
  filt.folder, filt.tag, page = nil, nil, 1
  pcall(function() ctx:after(1, step_search) end)
end

step_search = function()
  local s = search
  if not s or s.done then return end
  extend()
  local t0 = kit.now_ms() or 0
  while s.at < #entries do
    s.at = s.at + 1
    local e = entries[s.at]
    -- the title and the text, not the folder / tags / date lines (the filters cover those)
    local n = B.parse(B.read(e.name) or '')
    local line = B.find(n.title .. '\n' .. table.concat(n.paras, '\n'), s.f)
    if line then s.hits[e.name] = line end
    if (kit.now_ms() or 0) - t0 > 300 then break end
  end
  if s.at >= #entries then s.done = true
  else pcall(function() ctx:after(1, step_search) end) end
  kit.refresh()
end

------------------------------------------------------------------ pickers and menus

local function show_pick(title, items)
  pick = { title = title, items = items, page = 1, back = screen }
  screen = 'pick'
end

local function close_pick() screen = pick and pick.back or 'list'; pick = nil end

local function ask(title, text, max, fn)
  local ok, r, err = pcall(function()
    return ctx.input:text({ title = title, text = text or '', max_bytes = max or 120 }, function(c, s)
      if s then fn(s) end
      kit.refresh()
    end)
  end)
  if not ok then msg = 'The keyboard could not open.' end
end

local function folder_filter()
  local list, count, none = folders()
  local items = { { 'All folders (' .. #entries .. ')', function() filt.folder = nil end } }
  if none > 0 then items[#items + 1] = { 'No folder (' .. none .. ')', function() filt.folder = '' end } end
  for _k, f in ipairs(list) do items[#items + 1] = { f .. ' (' .. count[f] .. ')', function() filt.folder = f end } end
  show_pick('Folder', items)
end

local function tag_filter()
  local items = { { 'All tags', function() filt.tag = nil end } }
  for _k, t in ipairs(tags()) do items[#items + 1] = { t[1] .. ' (' .. t[2] .. ')', function() filt.tag = t[1] end } end
  show_pick('Tag', items)
end

local SORT_LABEL = { edited = 'Edited', title = 'Title', created = 'Created' }
local function sort_menu()
  local function o(k, label) return { label, function() kit.close(); sort, page = k, 1; save_settings() end } end
  kit.show({ title = 'Sort the notes', rows = { { o('edited', 'Last edited') }, { o('title', 'Title A-Z') },
                                               { o('created', 'Newest first') }, { { 'Cancel', kit.close } } },
             cancel = kit.close })
end

local function new_note()
  ask('Title of the new note', '', 120, function(s)
    s = B.trim(s:gsub('[\r\n]', ' '))
    if s == '' then return end
    local stamp = now_text()
    local n = { title = s, folder = filt.folder or '', tags = filt.tag and { filt.tag } or {}, edited = stamp, created = stamp, paras = {} }
    local name = B.file_name(s, taken_by_other(nil))
    local ok, err = store_note(name, n)
    if not ok then msg = err; return end
    search = nil
    cur = { name = name, n = n, page = 1 }
    screen = 'note'
    start_edit(nil)
  end)
end

local function set_folder(f)
  cur.n.folder = f
  cur.n.edited = now_text()
  local ok, err = store_note(cur.name, cur.n)
  msg = ok and (f == '' and 'No folder.' or ('In folder ' .. f .. '.')) or err
end

local function folder_menu()
  local list = folders()
  local items = { { 'No folder', function() set_folder('') end } }
  for _k, f in ipairs(list) do items[#items + 1] = { f, function() set_folder(f) end } end
  items[#items + 1] = { 'New folder...', function()
    ask('Name of the new folder', '', 60, function(s)
      s = B.trim(s:gsub('[\r\n\t]', ' '))
      if s ~= '' then set_folder(s) end
    end)
  end }
  show_pick('Folder of this note', items)
end

local function rename()
  ask('Title', cur.n.title, 120, function(s)
    s = B.trim(s:gsub('[\r\n]', ' '))
    if s == '' or s == cur.n.title then return end
    local old = cur.name
    local name = B.file_name(s, taken_by_other(old))
    if name:lower() == old:lower() then name = old end
    cur.n.title, cur.n.edited = s, now_text()
    local ok, err = store_note(name, cur.n)
    if not ok then msg = err; return end
    if name ~= old then
      B.remove(old)
      local _e, k = entry_of(old)
      if k then table.remove(entries, k) end
      B.save_index(entries)
      cur.name = name
    end
    msg = 'Renamed.'
  end)
end

local function edit_tags()
  ask('Tags, with commas between them', table.concat(cur.n.tags, ', '), 200, function(s)
    cur.n.tags = B.split_tags(s:gsub('[\r\n]', ' '))
    cur.n.edited = now_text()
    local ok, err = store_note(cur.name, cur.n)
    msg = ok and (#cur.n.tags > 0 and ('Tags: ' .. table.concat(cur.n.tags, ', ')) or 'No tags.') or err
  end)
end

local function delete_note()
  kit.show({ title = 'Delete "' .. kit.short(cur.n.title, 28) .. '"?', lines = { 'The note\'s file is removed from the card.' },
             rows = { { { 'Delete', function()
                          kit.close()
                          B.remove(cur.name)
                          local _e, k = entry_of(cur.name)
                          if k then table.remove(entries, k) end
                          B.save_index(entries)
                          cur, screen, msg = nil, 'list', 'Note deleted.'
                        end },
                        { 'Cancel', kit.close } } },
             cancel = kit.close })
end

local function note_menu()
  kit.show({ title = kit.short(cur.n.title, 30),
             rows = { { { 'Rename', function() kit.close(); rename() end }, { 'Folder', function() kit.close(); folder_menu() end } },
                      { { 'Tags', function() kit.close(); edit_tags() end }, { 'Delete', function() kit.close(); delete_note() end } },
                      { { 'Close', kit.close } } },
             cancel = kit.close })
end

------------------------------------------------------------------ drawing

local function meta(e)
  local t = {}
  if e.folder ~= '' then t[#t + 1] = e.folder end
  if #e.tags > 0 then t[#t + 1] = '#' .. table.concat(e.tags, ' #') end
  local d = (sort == 'created' and e.created or e.edited):sub(1, 10)
  if d ~= '' then t[#t + 1] = d end
  return table.concat(t, '  ·  ')
end

local function filter_buttons()
  local folder_l = filt.folder == nil and 'Folders' or (filt.folder == '' and 'No folder' or filt.folder)
  local tag_l = filt.tag and ('#' .. filt.tag) or 'Tags'
  return { { folder_l, folder_filter }, { tag_l, tag_filter }, { SORT_LABEL[sort], sort_menu },
           { search and 'Clear' or 'Search', function()
               if search then search = nil; page = 1
               else ask('Search all notes', '', 64, function(s) start_search(s) end) end
             end } }
end

local function bottom_buttons()
  if screen == 'list' then
    return { { '<', function() page = math.max(1, page - 1) end }, { 'New note', new_note },
             { '>', function() page = math.min(pages(#visible()), page + 1) end } }
  elseif screen == 'note' then
    local n = #note_pages()
    return { { 'List', function() cur, screen = nil, 'list' end }, { '<', function() cur.page = math.max(1, cur.page - 1) end },
             { 'Add', function() start_edit(nil) end }, { '>', function() cur.page = math.min(n, cur.page + 1) end } }
  elseif screen == 'pick' then
    local n = math.max(1, (#pick.items + 8) // 9)
    return { { '<', function() pick.page = math.max(1, pick.page - 1) end }, { 'Cancel', close_pick },
             { '>', function() pick.page = math.min(n, pick.page + 1) end } }
  end
  return {}
end

local function button_rects(bs, y, h)
  local out = {}
  local narrow = 0
  for _k, b in ipairs(bs) do if b[1] == '<' or b[1] == '>' then narrow = narrow + 1 end end
  local nw = 80
  local wide = #bs - narrow
  local ww = wide > 0 and (W - 24 - (#bs - 1) * 8 - narrow * nw) // wide or 0
  local x = 12
  for k, b in ipairs(bs) do
    local bw = (b[1] == '<' or b[1] == '>') and nw or ww
    out[k] = { x, y, bw, h }
    x = x + bw + 8
  end
  return out
end

local function draw_list(gg)
  local f, fs = kit.font('large'), kit.font('small')
  gg:text(12, 8, 'Notebook', { font = f })
  local vis = visible()
  local count = #vis .. (#vis == 1 and ' note' or ' notes')
  gg:text(W - 12 - kit.width(fs, count), 18, count, { font = fs })
  local fb = filter_buttons()
  for k, r in ipairs(button_rects(fb, 52, 44)) do kit.button(gg, r[1], r[2], r[3], r[4], fb[k][1], { font = 'small', line_width = 1 }) end
  if search then
    local s = search.done and ('Found in ' .. #vis .. ' of ' .. #entries .. ': "' .. search.q .. '"')
      or ('Searching... ' .. search.at .. '/' .. search.n)
    gg:text(12, 106, kit.short(s, 46), { font = fs })
  end
  local top = list_top()
  if page > pages(#vis) then page = pages(#vis) end
  local first = (page - 1) * per_page() + 1
  for k = first, math.min(#vis, first + per_page() - 1) do
    local e = vis[k]
    local y = top + (k - first) * ROW_H
    gg:text(12, y + 6, kit.short(e.title, 34), { font = kit.font('medium') })
    gg:text(12, y + 34, kit.short(meta(e), 50), { font = fs })
    local third = search and search.hits[e.name] or e.snip
    gg:text(12, y + 54, kit.short(third, 50), { font = fs })
    gg:line(8, y + ROW_H - 2, W - 8, y + ROW_H - 2)
  end
  if #vis == 0 then
    local t = #entries == 0 and 'No notes yet: tap New note.' or (search and (search.done and 'No note has that.' or '') or 'No notes in this folder or tag.')
    gg:text(16, top + 20, t, { font = kit.font('medium') })
  end
  if pages(#vis) > 1 then
    local p = page .. '/' .. pages(#vis)
    gg:text(W - 12 - kit.width(fs, p), BODY_END - 4, p, { font = fs })
  end
end

local function draw_note(gg)
  local fs = kit.font('small')
  local n = cur.n
  gg:text(12, 8, kit.short(n.title, 26), { font = kit.font('large') })
  kit.button(gg, W - 102, 6, 90, 40, 'Menu', { font = 'medium' })
  local m = {}
  if n.folder ~= '' then m[#m + 1] = n.folder end
  if #n.tags > 0 then m[#m + 1] = '#' .. table.concat(n.tags, ' #') end
  if #m == 0 then m[1] = 'No folder, no tags' end
  local pgs = note_pages()
  if cur.page > #pgs then cur.page = #pgs end
  local pi = cur.page .. '/' .. #pgs
  gg:text(12, 50, kit.short(table.concat(m, '  ·  '), 42), { font = fs })
  if #pgs > 1 then gg:text(W - 12 - kit.width(fs, pi), 50, pi, { font = fs }) end
  gg:line(0, 76, W, 76)
  if #n.paras == 0 then
    gg:text(16, BODY_Y + 10, 'Empty: tap Add to write.', { font = kit.font('medium') })
    return
  end
  local lh = kit.line_h('medium') + 2
  for _k, blk in ipairs(pgs[cur.page]) do
    for j, l in ipairs(blk.lines) do gg:text(16, blk.y + (j - 1) * lh, l, { font = kit.font('medium') }) end
  end
end

local function draw_edit(gg)
  local fs = kit.font('small')
  kit.button(gg, 12, 6, 110, 40, 'Cancel', { font = 'medium' })
  kit.button(gg, W - 122, 6, 110, 40, 'Save', { font = 'medium', line_width = 3 })
  local what = edit.i and ('Block ' .. edit.i .. ' of ' .. #cur.n.paras) or 'New block'
  gg:text((W - kit.width(fs, what)) // 2, 18, what, { font = fs })
  local r = edit_rect()
  gg:rect(r.x - 4, r.y - 4, r.w + 8, r.h + 8, { line_width = 1 })
  local count = (utf8.len(edit.text) or #edit.text) .. '/' .. B.MAX_BLOCK .. '   Enter: new line'
  gg:text(r.x, r.y + r.h + 6, count, { font = fs })
end

local function draw_pick(gg)
  gg:text(12, 8, pick.title, { font = kit.font('large') })
  local first = (pick.page - 1) * 9 + 1
  for k = first, math.min(#pick.items, first + 8) do
    local y = 62 + (k - first) * 70
    kit.button(gg, 12, y, W - 24, 60, kit.short(pick.items[k][1], 34), { font = 'medium', line_width = 1 })
  end
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    if kit.modal() then kit.draw_modal(gg); return end
    if screen == 'note' then draw_note(gg)
    elseif screen == 'edit' then draw_edit(gg)
    elseif screen == 'pick' then draw_pick(gg)
    else draw_list(gg) end
    if screen == 'edit' then return end
    local line = ERR and ('ERR ' .. ERR) or msg
    if line then gg:text(12, BTN_Y - 24, kit.short(line, 48), { font = kit.font('small') }) end
    local bs = bottom_buttons()
    for k, r in ipairs(button_rects(bs, BTN_Y, BTN_H)) do kit.button(gg, r[1], r[2], r[3], r[4], bs[k][1], { font = 'medium' }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 40, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function hit(rs, x, y)
  for k, r in ipairs(rs) do
    if x >= r[1] and x < r[1] + r[3] and y >= r[2] and y < r[2] + r[4] then return k end
  end
end

local function step_page(d)
  if screen == 'list' then page = math.max(1, math.min(pages(#visible()), page + d))
  elseif screen == 'note' then cur.page = math.max(1, math.min(#note_pages(), cur.page + d))
  elseif screen == 'pick' then pick.page = math.max(1, math.min((#pick.items + 8) // 9, pick.page + d)) end
end

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  if screen == 'edit' then
    if y < TOP_H then
      if x < 130 then cancel_edit() elseif x > W - 130 then save_edit() end
    end
    return
  end
  msg = nil
  local bs = bottom_buttons()
  local k = hit(button_rects(bs, BTN_Y, BTN_H), x, y)
  if k then bs[k][2](); return end
  if screen == 'list' then
    local fb = filter_buttons()
    k = hit(button_rects(fb, 52, 44), x, y)
    if k then fb[k][2](); return end
    local top = list_top()
    if y >= top and y < BODY_END then
      local vis = visible()
      local i = (page - 1) * per_page() + (y - top) // ROW_H + 1
      if (y - top) // ROW_H < per_page() and vis[i] then open_note(vis[i].name) end
    end
  elseif screen == 'note' then
    if y < 50 and x > W - 110 then note_menu(); return end
    if y >= BODY_Y and y < BODY_END then
      local lh = kit.line_h('medium') + 2
      local pgs = note_pages()
      for _j, blk in ipairs(pgs[cur.page] or {}) do
        if y >= blk.y - PARA_GAP // 2 and y < blk.y + #blk.lines * lh + PARA_GAP // 2 then start_edit(blk.i); return end
      end
    end
  elseif screen == 'pick' then
    local first = (pick.page - 1) * 9 + 1
    if y >= 62 and y < 62 + 9 * 70 then
      local i = first + (y - 62) // 70
      if (y - 62) % 70 < 60 and pick.items[i] then
        local fn = pick.items[i][2]
        close_pick()
        fn()
        page = 1
        save_settings()
      end
    end
  end
end

-- Back: closes a box, a list of choices or the note; on the list it clears a search, then is
-- left to the host, which offers to exit
local function go_back()
  if kit.modal() then
    if kit.modal().cancel then kit.modal().cancel() else kit.close() end
  elseif screen == 'pick' then close_pick()
  elseif screen == 'edit' then cancel_edit()
  elseif screen == 'note' then cur, screen = nil, 'list'
  elseif search then search, page = nil, 1
  else return false end
  return true
end

function on_input(c, ev)
  ERR = nil
  extend()
  local handled = true
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      local g = ev.gesture
      if (g == 'swipe_left' or g == 'swipe_right') and screen ~= 'edit' and not kit.modal() then
        step_page(g == 'swipe_left' and 1 or -1)
      elseif g == nil or g == 'tap' then
        tap(ev.x or 0, ev.y or 0)
      end
    elseif ev.type == 'key' and ev.key == 'back' then
      if ev.phase ~= nil and ev.phase ~= 'up' then return end
      handled = go_back()
    elseif ev.type == 'key' and kit.key_accepted(ev) and not kit.modal() and screen ~= 'edit' then
      if ev.key == 'up' or ev.key == 'left' then step_page(-1)
      elseif ev.key == 'down' or ev.key == 'right' then step_page(1) end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return handled
end

function on_load(c)
  extend()
  local ok, e = pcall(function()
    load_settings()
    entries = B.scan(function() extend() end)
  end)
  if not ok then ERR = tostring(e) end
end

function on_leave()
  if edit and edit.text ~= edit.start then
    -- the session ends while typing: keep what was written
    pcall(function() finish_edit(edit.text, true) end)
  end
end

if rawget(_G, '__TEST') then
  __TEST.api = { B = B, screen = function() return screen end, entries = function() return entries end,
                 cur = function() return cur end, edit = function() return edit end, search = function() return search end,
                 visible = visible, filt = filt, msg = function() return msg end, page = function() return page end,
                 note_pages = function() return note_pages() end }
end
